export default "<!doctype html>\n<html lang=\"pl\"><head><meta charset=\"utf-8\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src data:; style-src 'unsafe-inline' data:; script-src 'unsafe-inline'\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#07111d\"><title>Runiczny Duch</title>\n<style>\n:root{color-scheme:dark;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#eaf4fa;background:#07111d}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#153452 0%,#0a1928 31%,#07111d 70%);min-height:100vh}\nmain{max-width:760px;padding:18px 13px 70px;margin:auto}header{text-align:center;padding:13px 0 24px}h1{font:700 clamp(32px,8vw,46px) Georgia,serif;margin:1px 0 21px;letter-spacing:.4px;color:#f1faff}h2{font:700 23px Georgia,serif;margin:0}p{line-height:1.4}\n.stat{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pill{border:1px solid #36647c;border-radius:14px;padding:13px 6px;background:#132e3c;color:#c4e7ee;font-size:13px;min-width:0;overflow-wrap:anywhere;min-height:54px}\n.card{margin:14px 0;background:linear-gradient(132deg,#172938,#0e1d2b);border:1px solid #3c6072;border-radius:19px;padding:17px 15px;box-shadow:0 10px 24px #0003}.card.fog{border-color:#655b89}.card.water{border-color:#2d79ad}.card.light{border-color:#8b7252}\n.head{display:flex;gap:9px;align-items:center;justify-content:space-between}.name{display:flex;align-items:center;gap:10px}.ico{font-size:24px}.muted,.hint{color:#9db8c7;font-size:13px}.hint{display:block;margin:9px 0}.small{font-size:12px}.between{display:flex;align-items:center;justify-content:space-between;gap:9px}\nbutton{border:1px solid #49697b;background:#1c3948;color:#e9f8ff;cursor:pointer;border-radius:11px;padding:11px 12px;font-weight:650;font:inherit}button.active{border-color:#46dacf;box-shadow:inset 0 0 10px #1b7d78;color:#83fcf2;background:#164d52}button:disabled{opacity:.45;cursor:not-allowed}\nbutton:active{transform:translateY(1px)}.modes{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.modes button{width:100%}.minor{font-size:13px;padding:7px 10px;border-color:#3e6170}.danger{color:#f4a3a7;border-color:#87525a}.editrow{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}\ninput[type=range]{width:100%;accent-color:#62dbdd;cursor:pointer}.water input[type=range]{accent-color:#46aaff}.light input[type=range]{accent-color:#ffd08c}input[type=time],input[type=number],select{background:#0a1e2c;color:#e7f4f8;border:1px solid #587487;border-radius:8px;padding:9px 4px;min-width:0;max-width:100%;font:inherit}\n.power{margin:11px 0}.power strong{float:right;color:#8aece4}.fold{margin:13px 0 2px;border-top:1px solid #35505c;padding-top:12px}summary{cursor:pointer;font-weight:650;color:#a6eaf6;padding:6px 0}.timeRow{display:grid;grid-template-columns:19px minmax(0,1fr) 12px minmax(0,1fr) 48px 30px;gap:4px;align-items:center;margin:7px 0}.timeRow.fogRow{grid-template-columns:19px minmax(0,1fr) 12px minmax(0,1fr) 30px}.timeRow input[type=time]{width:100%;font-size:13px;padding:9px 1px}.timeRow input[type=number]{width:100%;font-size:13px;padding:9px 2px}.timeRow .minor{padding:8px 3px}.times{display:grid;grid-template-columns:1fr 1fr;gap:8px}.times label{font-size:13px;color:#c6dbe3}.times input{display:block;width:100%;margin-top:5px}\n.save{background:#166d70;border-color:#44c6c5;width:100%;margin:12px 0 0;font-weight:700}.device{padding:14px 0;border-bottom:1px solid #345260}.device:last-child{border:0}.empty{text-align:center;padding:14px;color:#a1bfca}.add{width:100%;margin-top:14px;border-color:#3ba8a6;padding:15px;background:#124448}.adder{margin:12px 0;padding:15px;border:1px solid #49798c;border-radius:16px;background:#102a3b}.adder label{display:block;margin:9px 0;color:#cbe2e9;font-size:14px}.adder select{width:100%;display:block;margin-top:5px}.toast{position:fixed;bottom:15px;left:12px;right:12px;max-width:710px;margin:auto;padding:12px 16px;border:1px solid #35bdbd;border-radius:11px;background:#163e45;color:white;display:none;box-shadow:0 8px 32px #0009;z-index:9}.fine{color:#9db8c7;font-size:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n@media(min-width:600px){.timeRow{grid-template-columns:28px 1fr 16px 1fr 64px 34px}.timeRow.fogRow{grid-template-columns:28px 1fr 16px 1fr 34px}}\n\n/* Gorne rozwijane panele: WIFI i Aktualizacje. */\n.topButton{cursor:pointer;text-align:center;line-height:1.4;font:600 12.5px/1.4 system-ui;white-space:normal;width:100%}\n.topButton[aria-expanded=true]{border-color:#65e2df;background:#154b55}\n.topPanel{margin-top:11px;border:1px solid #3a8191;background:linear-gradient(125deg,#142e3c,#0c2534);border-radius:17px;padding:16px 13px;text-align:left}\n.topPanel[hidden],.renameEditor[hidden],.adder[hidden]{display:none!important}\n.topPanel h3{font:700 19px Georgia,serif;margin:0 0 10px}\n.topPanel label,.adder label{display:block;font-size:13px;color:#c7e2ed;margin:10px 0}\n.topPanel input[type=text],.topPanel input[type=password],.adder input[type=text],.renameEditor input[type=text]{width:100%;min-width:0;padding:11px;background:#071d2b;border:1px solid #4a778b;border-radius:10px;font:inherit;color:#eaf9fa;margin-top:6px}\n.topPanel button{max-width:100%}.networkList{max-height:205px;overflow:auto;margin:9px 0;border-radius:10px}\n.networkChoice{width:100%;text-align:left;display:flex;gap:8px;justify-content:space-between;margin:4px 0;padding:10px 12px}\n.networkChoice.selected{border-color:#75e4d6;background:#194c57}.networkChoice small{font-size:11px;color:#b3d5de}\n.renameEditor{padding:10px 0 2px;display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap}\n.renameEditor input{flex:1;min-width:140px}.renameEditor button{align-self:end}\n.subtitle{font-size:12px;color:#a4d3df;margin:9px 0}.topPanel form input[type=file]{max-width:100%;font-size:12px;padding:9px 0}\n.closeTop{display:block;width:100%;margin-top:10px}\n.updateStatus{border:1px solid #365d6e;padding:11px;border-radius:10px;color:#c7e5ea;font-size:13px;margin-top:10px;white-space:pre-wrap}\n.updateStatus.error{border-color:#a45660;color:#f5b4bf}\n.updateStatus.success{border-color:#368a73;color:#b1f6d8}\n.topPanel input[type=text].githubRepo{max-width:100%}\n\n/* Wlasna nazwa ESP i ikony - zapis w osobnych przestrzeniach NVS. */\n.espHeading{display:flex;justify-content:center;align-items:center;gap:8px;flex-wrap:wrap}\n.espHeading h1{overflow-wrap:anywhere;min-width:0;margin-bottom:20px}\n.editEsp{border:1px solid #356579;border-radius:10px;padding:6px 9px;margin-bottom:17px;font-size:14px;background:#153748;color:#baf7f5}\n.espNameEditor{padding:11px;margin:0 auto 15px;max-width:480px;border:1px solid #368b9c;border-radius:12px;background:#102a3a;text-align:left}\n.espNameEditor[hidden],.iconEditor[hidden]{display:none!important}\n.espNameEditor label{display:block;color:#b6e2e8;font-size:13px}\n.espNameEditor input{width:100%;font:inherit;border:1px solid #4a778b;background:#071d2b;color:#eaf9fa;border-radius:8px;padding:10px;margin:5px 0 9px}\n.espNameEditor .two button{width:100%}\n.icoImg{width:45px;height:45px;object-fit:cover;border-radius:12px;border:1px solid #245e69;flex-shrink:0}\n.iconChoices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:8px 0 12px}\n.iconPick{display:flex;flex-direction:column;align-items:center;gap:5px;padding:7px 4px;border-radius:12px;color:#aee4ed;font-size:12px}\n.iconPick img{width:56px;height:56px;object-fit:cover;border-radius:10px}\n.iconPick[aria-pressed=true]{border-color:#51e6dd;background:#18545a;box-shadow:inset 0 0 0 1px #51e6dd}\n.iconEditor{padding:11px 0;border-top:1px solid #345260;margin-top:9px}\n</style></head><body><main>\n<header><div class=\"espHeading\"><h1 id=\"espDisplayName\">Runiczny Duch</h1>\n<button type=\"button\" class=\"editEsp\" onclick=\"toggleEspNameEditor()\" title=\"Zmień nazwę tego ESP\" aria-label=\"Zmień nazwę tego ESP\">✎</button></div>\n<div class=\"espNameEditor\" id=\"espNameEditor\" hidden>\n<label>Własna nazwa tego sterownika ESP<input type=\"text\" id=\"espNameInput\" maxlength=\"64\" placeholder=\"Wpisz nazwę swojego ESP\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();saveEspName()}else if(event.key==='Escape'){toggleEspNameEditor(false)}\"></label>\n<div class=\"two\"><button type=\"button\" onclick=\"toggleEspNameEditor(false)\">Anuluj</button>\n<button type=\"button\" class=\"active\" onclick=\"saveEspName()\">Zapisz nazwę</button></div></div>\n<div class=\"stat\"><button class=\"pill topButton\" id=\"wifi\" aria-expanded=\"false\" onclick=\"toggleTopPanel('network')\">📶 Wi-Fi: sprawdzanie ▾</button>\n<button class=\"pill topButton\" id=\"time\" aria-expanded=\"false\" onclick=\"toggleTopPanel('updates')\">📅 Data · Aktualizacje ▾</button></div>\n<div class=\"topPanel\" id=\"networkPanel\" hidden>\n<h3>📶 Sieci Wi-Fi</h3>\n<p class=\"subtitle\" id=\"wifiDetails\">Wyszukaj sieci w pobliżu lub wpisz nazwę ręcznie.</p>\n<button class=\"minor\" onclick=\"scanWifi()\">⟳ Wyszukaj dostępne sieci</button>\n<div class=\"networkList\" id=\"wifiNetworks\" aria-live=\"polite\"></div>\n<label>Wybrana sieć (SSID)<input type=\"text\" id=\"homeSsid\" maxlength=\"32\" placeholder=\"Wybierz z listy lub wpisz nazwę\"></label>\n<label>Hasło wybranej sieci<input type=\"password\" id=\"homePass\" maxlength=\"64\" placeholder=\"Dla tej samej sieci można pozostawić puste\"></label>\n<button class=\"save\" onclick=\"saveHomeWifi()\">Zapisz Wi-Fi i połącz</button>\n<p class=\"fine\">Przy pierwszym połączeniu wybierz sieć 2,4 GHz. Zapis powoduje restart ESP.</p>\n\n<button class=\"minor closeTop\" onclick=\"closeTopPanels()\">Zwiń ustawienia Wi-Fi ↑</button>\n</div>\n<div class=\"topPanel\" id=\"updatesPanel\" hidden>\n<h3>📅 Data i aktualizacje</h3>\n<p class=\"subtitle\" id=\"firmwareVersion\">Wersja firmware: —</p>\n<p class=\"subtitle\" id=\"deviceClock\">Czas sterownika: —</p>\n<button class=\"minor\" onclick=\"updateClock()\">⟳ Synchronizuj zegar z telefonem</button>\n<p class=\"fine\">Aktualizacja z konta klienta nie jest dostępna w tej wersji próbnej.</p><div class=\"fold\"><strong>Dane logowania</strong><label>Nowy login<input id=\"clientLogin\" maxlength=\"32\" autocomplete=\"username\"></label><label>Nowe hasło<input id=\"clientPassword\" maxlength=\"63\" type=\"password\" autocomplete=\"new-password\"></label><button class=\"save\" onclick=\"saveClientAccount()\">Zapisz login i hasło</button></div></div></header>\n<section id=\"sections\">Ładowanie sterownika…</section>\n\n</main><div id=\"toast\" class=\"toast\"></div>\n<script>\nwindow.addEventListener('error',function(e){var el=document.getElementById('sections');if(el&&document.documentElement.dataset.uiReady!=='1')el.textContent='BŁĄD JAVASCRIPT: '+(e.message||'nieznany');});\nwindow.addEventListener('unhandledrejection',function(e){var el=document.getElementById('sections');if(el&&document.documentElement.dataset.uiReady!=='1')el.textContent='BŁĄD STARTU: '+String(e.reason||'nieznany');});\nsetTimeout(function(){var el=document.getElementById('sections');if(el&&document.documentElement.dataset.uiReady!=='1'&&el.textContent.indexOf('Ładowanie')>=0)el.textContent='Panel nie załadował się.';},18000);\n</script><script>'use strict';\nlet state=null,toastTimer;\nconst channelNames=['Neuron 1','Neuron 2','Neuron 3','Neuron 4','Neuron 5'];\nconst iconNames=['Światło','Kropla','Wodospad','Rzeka','Deszcz','Mgła'];\nfunction iconImg(id,klass='icoImg'){\n  const safe=Number.isInteger(Number(id))&&Number(id)>=0&&Number(id)<6?Number(id):1;\n  return `<img class=\"${klass}\" src=\"${clientIcons[safe]}\" alt=\"\" loading=\"lazy\">`;\n}\nfunction iconPickerHtml(current,callback,ch){\n  return iconNames.map((name,i)=>{\n    const disabled=ch===3&&i!==5;\n    return `<button type=\"button\" class=\"iconPick\" aria-label=\"${esc(name)}\" aria-pressed=\"${Number(current)===i}\" ${disabled?'disabled title=\"Neuron 4: tylko ON/OFF\"':''} onclick=\"${callback}(${i})\">${iconImg(i,'')}<span>${esc(name)}</span></button>`;\n  }).join('');\n}\nfunction typeFromIcon(icon){return icon===0?1:(icon===5?2:3);}\nfunction toggleEspNameEditor(force){\n  const box=document.getElementById('espNameEditor');\n  box.hidden=typeof force==='boolean'?!force:!box.hidden;\n  if(!box.hidden){const input=document.getElementById('espNameInput');input.value=state?.espName||'Runiczny Duch';input.focus();input.select();}\n}\nasync function saveEspName(){\n  const value=document.getElementById('espNameInput').value.trim();\n  if(!value||new TextEncoder().encode(value).length>64){flash('Nazwa ESP musi mieć 1–64 bajty',true);return;}\n  if(await send('/api/esp-name',{name:value},'Zapisano nazwę ESP'))toggleEspNameEditor(false);\n}\n\nlet remoteCandidate=null,remoteBusy=false;\nfunction esc(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));}\nfunction hhmm(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}\nfunction flash(t,error=false){const e=document.getElementById('toast');e.textContent=t;e.style.borderColor=error?'#e77777':'#35bdbd';e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',3800);}\n\nconst clientIcons=[\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\"];\nlet requestId=0;\nconst pending=new Map();\nwindow.rdClientReply=function(reply){\n  const entry=pending.get(reply.id);\n  if(!entry)return;\n  pending.delete(reply.id);\n  clearTimeout(entry.timer);\n  if(reply.error)entry.reject(new Error(reply.error));\n  else entry.resolve(reply.data);\n};\nfunction req(url,params){\n  return new Promise((resolve,reject)=>{\n    const id=++requestId;\n    const timer=setTimeout(()=>{pending.delete(id);reject(new Error('ESP nie odpowiedział'));},20000);\n    pending.set(id,{resolve,reject,timer});\n    window.ReactNativeWebView.postMessage(JSON.stringify({id,url,params}));\n  });\n}\nasync function saveClientAccount(){\n  const login=document.getElementById('clientLogin');\n  const password=document.getElementById('clientPassword');\n  if(!/^[A-Za-z0-9_.-]{3,32}$/.test(login.value)||password.value.length<8){\n    flash('Sprawdź login i hasło. Hasło musi mieć co najmniej 8 znaków.',true);\n    return;\n  }\n  try{\n    await req('/client-account',{user:login.value,password:password.value});\n    password.value='';\n    flash('Zapisano nowe dane klienta.');\n  }catch(error){flash(error.message,true);}\n}\nasync function send(url,params,notice='Zapisano'){try{const result=await req(url,params);if(!result||!Array.isArray(result.channels))throw Error('Niepełna odpowiedź sterownika');state=result;paint();flash(notice);return true;}\n  catch(e){flash('Błąd: '+e.message,true);return false;}}\nfunction modeButtons(d){\n  const ch=d.ch;return `<div class=\"modes\"><button class=\"${d.mode===2?'active':''}\" onclick=\"setManual(${ch})\">${d.mode===2?'ON ●':'ON / OFF'}</button><button class=\"${d.mode===1?'active':''}\" onclick=\"setAuto(${ch})\">AUTO</button></div>`;\n}\nfunction setManual(ch){const d=state.channels[ch];send('/api/mode',{ch,mode:d.mode===2?0:2},d.mode===2?'Wyłączono':'Włączono ręcznie');}\nfunction setAuto(ch){const d=state.channels[ch];send('/api/mode',{ch,mode:d.mode===1?0:1},d.mode===1?'AUTO wyłączone':'AUTO włączone');}\nfunction powerRow(d,label){const ch=d.ch;return `<div class=\"power\"><label>${esc(label)} <strong id=\"pct${ch}\">${d.power}%</strong></label><input type=\"range\" min=\"0\" max=\"100\" value=\"${d.power}\" oninput=\"document.getElementById('pct${ch}').textContent=this.value+'%'\" onchange=\"send('/api/power',{ch:${ch},value:this.value})\"></div>`;}\nfunction channelDisplay(d){return d.name||channelNames[d.ch];}\nfunction iconEditor(d){return `<div class=\"iconEditor\" id=\"iconEditor${d.ch}\" hidden><p class=\"hint\">Wybierz ikonę dla ${esc(channelDisplay(d))}</p>\n<div class=\"iconChoices\">${iconPickerHtml(d.icon,`saveChannelIcon.bind(null,${d.ch})`,d.ch)}</div></div>`;}\nfunction toggleIconEditor(ch){const el=document.getElementById('iconEditor'+ch);if(el)el.hidden=!el.hidden;}\nasync function saveChannelIcon(ch,icon){await send('/api/icon',{ch,icon},'Zapisano ikonę');}\n\nfunction nameEditor(d){const ch=d.ch;return `<div class=\"renameEditor\" id=\"renameBox${ch}\" hidden><input type=\"text\" id=\"renameInput${ch}\" aria-label=\"Nowa nazwa kanału\" maxlength=\"48\" value=\"${esc(channelDisplay(d))}\">\n<button class=\"minor active\" onclick=\"saveChannelName(${ch})\">Zapisz nazwę</button></div>`;}\nfunction toggleNameEditor(ch){const el=document.getElementById('renameBox'+ch);if(!el)return;el.hidden=!el.hidden;if(!el.hidden)document.getElementById('renameInput'+ch).focus();}\nasync function saveChannelName(ch){const value=document.getElementById('renameInput'+ch).value.trim();if(!value||new TextEncoder().encode(value).length>48){flash('Nazwa musi mieć 1–48 bajtów',true);return;}await send('/api/rename',{ch,name:value},'Zmieniono nazwę CH'+(ch+1));}\nfunction lightTimes(d){const ch=d.ch;return `<details class=\"fold\" id=\"light${ch}\"><summary>🌅 Świt → Dzień → Zmierzch · ${channelNames[ch]}</summary>\n<div class=\"times\"><label>Świt OD<input type=\"time\" id=\"dawnFrom${ch}\" value=\"${hhmm(d.dawnFrom)}\"></label>\n<label>Świt DO<input type=\"time\" id=\"dawnTo${ch}\" value=\"${hhmm(d.dawnTo)}\"></label>\n<label>Zmierzch OD<input type=\"time\" id=\"duskFrom${ch}\" value=\"${hhmm(d.duskFrom)}\"></label>\n<label>Zmierzch DO<input type=\"time\" id=\"duskTo${ch}\" value=\"${hhmm(d.duskTo)}\"></label></div>\n<button class=\"save\" onclick=\"saveLight(${ch})\">Zapisz godziny · ${channelNames[ch]}</button></details>`;}\nfunction lightCard(lights){if(!lights.length)return '';\n  return lights.map(d=>{const name=channelDisplay(d),ch=d.ch;\n    return `<article class=\"card light\"><div class=\"head\"><div class=\"name\">${iconImg(d.icon)}<h2>${esc(name)}</h2></div>\n<span><button class=\"minor\" onclick=\"toggleNameEditor(${ch})\" aria-label=\"Zmień nazwę\">✎</button> <button class=\"minor\" onclick=\"toggleIconEditor(${ch})\" aria-label=\"Zmień ikonę\">◈</button> </span></div>\n${nameEditor(d)}${iconEditor(d)}${modeButtons(d)}${powerRow(d,'Jasność')}${lightTimes(d)}</article>`;\n  }).join('');}\nfunction slotRow(ch,s,i,type){const pow=type===3;return `<div class=\"timeRow ${pow?'':'fogRow'}\" data-slot=\"${ch}\">\n<span class=\"fine rowNumber\">${i+1}.</span>\n<input type=\"time\" aria-label=\"Od\" class=\"from\" value=\"${hhmm(s.from)}\"><span class=\"fine\">→</span>\n<input type=\"time\" aria-label=\"Do\" class=\"to\" value=\"${hhmm(s.to)}\">\n${pow?`<input type=\"number\" min=\"0\" max=\"100\" aria-label=\"Moc procent\" class=\"slotPower\" value=\"${s.power}\" title=\"Moc %\">`:''}\n<button class=\"minor danger\" onclick=\"deleteSlot(this,${ch})\" title=\"Usuń cykl\">×</button></div>`;}\nfunction schedules(d){const ch=d.ch;return `<details class=\"fold\" id=\"slots${ch}\"><summary>📅 Harmonogram</summary>\n<div class=\"fine between\"><span>OD → DO${d.type===3?' · Moc %':''}</span><span id=\"count${ch}\">${d.slots.length} / 24</span></div>\n<div id=\"slotRows${ch}\">${d.slots.length?d.slots.map((s,i)=>slotRow(ch,s,i,d.type)).join(''):'<p class=\"empty\">Brak zapisanych cykli</p>'}</div>\n<button class=\"minor\" id=\"addSlot${ch}\" onclick=\"addSlot(${ch})\" ${d.slots.length>=24?'disabled':''}>＋ Dodaj cykl</button>\n<button class=\"save\" onclick=\"saveSlots(${ch})\">Zapisz harmonogram</button></details>`;}\nfunction deviceCard(d){const name=channelDisplay(d);\n  return `<article class=\"card ${d.type===2?'fog':'water'}\"><div class=\"head\"><div class=\"name\">${iconImg(d.icon)}<h2>${esc(name)}</h2></div>\n<span><button class=\"minor\" onclick=\"toggleNameEditor(${d.ch})\">✎</button> <button class=\"minor\" onclick=\"toggleIconEditor(${d.ch})\" aria-label=\"Zmień ikonę\">◈</button> </span></div>\n<p class=\"fine\">${esc(channelNames[d.ch])} · ${d.pwm?'PWM':'ON/OFF'}</p>${nameEditor(d)}${iconEditor(d)}\n${modeButtons(d)}${d.type===3?powerRow(d,'Moc · '+name):''}${schedules(d)}</article>`;}\nfunction paint(){if(!state)return;const open=Array.from(document.querySelectorAll('details[open]')).map(x=>x.id).filter(Boolean);\n  const light=state.channels.filter(d=>d.type===1),fog=state.channels.filter(d=>d.type===2),water=state.channels.filter(d=>d.type===3);\n  const html=lightCard(light)+fog.map(deviceCard).join('')+water.map(deviceCard).join('');\n  document.getElementById('sections').innerHTML=html||'<p class=\"empty\">Nie dodano jeszcze urządzeń.</p>';\n  open.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});statusOnly();\n}\nfunction statusOnly(){if(!state)return;\n const ssid=state.activeSsid||'brak';\n const espName=state.espName||'Runiczny Duch';\n document.getElementById('espDisplayName').textContent=espName;\n document.title=espName+' · Runiczny Duch';\n document.getElementById('wifi').textContent='📶 Sieć: '+ssid+' ▾';\n document.getElementById('time').textContent='📅 '+(state.clockValid?state.clock:'Brak godziny')+' · Aktualizacje ▾';\n document.getElementById('wifiDetails').textContent='Aktualnie: '+ssid+(state.sta?' (domowa)':' (lokalna)');\n document.getElementById('deviceClock').textContent='Czas sterownika: '+(state.clockValid?state.clock:'brak synchronizacji');\n document.getElementById('firmwareVersion').textContent='Firmware: Runiczny Duch '+(state.build||state.version||'—')+' · OTA '+(state.otaSupported?'gotowe':'niedostępne');\n}\nfunction closeTopPanels(){\n  ['network','updates'].forEach(id=>{\n    document.getElementById(id+'Panel').hidden=true;\n    document.getElementById(id==='network'?'wifi':'time').setAttribute('aria-expanded','false');\n  });\n  wifiScanAttempts=0;\n}\nfunction toggleTopPanel(section){\n  const panel=document.getElementById(section+'Panel');\n  const shouldOpen=panel.hidden;\n  closeTopPanels();\n  if(shouldOpen){\n    panel.hidden=false;\n    document.getElementById(section==='network'?'wifi':'time').setAttribute('aria-expanded','true');\n    if(section==='network')scanWifi();\n  }\n}\nlet wifiScanAttempts=0;\nasync function scanWifi(retry=false){\n if(document.getElementById('networkPanel').hidden)return;\n const host=document.getElementById('wifiNetworks');if(!retry)wifiScanAttempts=0;\n host.textContent='Szukam dostępnych sieci 2,4 GHz…';\n if(++wifiScanAttempts>25){host.textContent='Skanowanie nie odpowiada. Spróbuj ponownie.';return;}\n try{const data=await req('/api/wifi-scan');\n  if(data.status==='scanning'){if(!document.getElementById('networkPanel').hidden)setTimeout(()=>scanWifi(true),800);return;}\n  if(document.getElementById('networkPanel').hidden)return;\n  if(data.status!=='done'||!Array.isArray(data.networks))throw Error('Skanowanie nieudane');\n  if(!data.networks.length){host.textContent='Nie znaleziono sieci. Możesz wpisać SSID ręcznie.';return;}\n  host.innerHTML=data.networks.map(n=>`<button class=\"networkChoice ${n.ssid===document.getElementById('homeSsid').value?'selected':''}\" data-ssid=\"${esc(n.ssid)}\" onclick=\"chooseWifi(this)\"><span>📶 ${esc(n.ssid)}</span><small>${n.secure?'🔒 ':''}${n.rssi} dBm</small></button>`).join('');\n }catch(e){host.textContent='Nie udało się pobrać sieci: '+e.message+' — możesz wpisać nazwę ręcznie.';}\n}\nfunction chooseWifi(btn){const ssid=btn.dataset.ssid;document.getElementById('homeSsid').value=ssid;document.getElementById('homePass').value='';document.querySelectorAll('.networkChoice').forEach(el=>el.classList.toggle('selected',el===btn));}\nasync function refresh(){try{const next=await req('/api/state');if(Array.isArray(next.channels)){state=next;statusOnly();}}catch(e){document.getElementById('wifi').textContent='📶 Wi-Fi: brak połączenia';}}\nasync function saveLight(ch){const params={ch};for(const n of ['dawnFrom','dawnTo','duskFrom','duskTo'])params[n]=document.getElementById(n+ch).value;\n  const values=Object.values(params).slice(1);if(values.some(v=>!/^\\d\\d:\\d\\d$/.test(v))){flash('Uzupełnij wszystkie godziny',true);return;}\n  await send('/api/light',params,'Zapisano świt i zmierzch');}\nfunction recount(ch){const rows=[...document.querySelectorAll('#slotRows'+ch+' .timeRow')];rows.forEach((r,i)=>r.querySelector('.rowNumber').textContent=(i+1)+'.');\n  document.getElementById('count'+ch).textContent=rows.length+' / 24';document.getElementById('addSlot'+ch).disabled=rows.length>=24;}\nfunction addSlot(ch){const d=state.channels[ch];const host=document.getElementById('slotRows'+ch);let rows=host.querySelectorAll('.timeRow');if(rows.length>=24){flash('Maksymalnie 24 cykle',true);return;}\n  const empty=host.querySelector('.empty');if(empty)empty.remove();host.insertAdjacentHTML('beforeend',slotRow(ch,{from:480,to:490,power:60},rows.length,d.type));recount(ch);}\nfunction deleteSlot(button,ch){button.closest('.timeRow').remove();const host=document.getElementById('slotRows'+ch);\n  if(!host.querySelector('.timeRow'))host.innerHTML='<p class=\"empty\">Brak cykli</p>';recount(ch);}\nasync function saveSlots(ch){const d=state.channels[ch];const rows=[...document.querySelectorAll('#slotRows'+ch+' .timeRow')];if(rows.length>24){flash('Maksymalnie 24 cykle',true);return;}\n  const out=[];for(const r of rows){const from=r.querySelector('.from').value,to=r.querySelector('.to').value,power=d.type===3?r.querySelector('.slotPower').value:'100';\n    if(!from||!to||from===to||!/^(100|[1-9]?\\d)$/.test(String(power))){flash('Sprawdź OD, DO i moc 0–100%',true);return;}\n    out.push([from,to,power].join('|'));}\n  await send('/api/slots',{ch,rows:out.join(';')},'Harmonogram zapisany');}\nasync function saveHomeWifi(){\n  const ssid=document.getElementById('homeSsid').value.trim();\n  const pwd=document.getElementById('homePass').value;\n  if(!ssid||ssid.length>32||pwd.length<8||pwd.length>63){flash('Sprawdź dane Wi-Fi',true);return;}\n  if(!confirm('Zapisac dane sieci '+ssid+' i uruchomic ESP ponownie?'))return;\n  try{await req('/api/wifi',{ssid,pwd});closeTopPanels();flash('Zapisano Wi-Fi. ESP uruchomi sie ponownie.');}\n  catch(e){flash('Błąd zapisu Wi-Fi: '+e.message,true);}\n}\nasync function updateClock(){try{state=await req('/api/time',{epoch:Math.floor(Date.now()/1000)});statusOnly();flash('Zegar zsynchronizowany');}\n  catch(e){flash('Błąd synchronizacji: '+e.message,true);}}\nasync function syncClock(){if(state&&state.clockValid)return;try{await req('/api/time',{epoch:Math.floor(Date.now()/1000)});}catch(e){}}\ndocument.addEventListener('click',e=>{\n  if(!e.target.closest('#networkPanel,#updatesPanel,#wifi,#time') &&\n     (!document.getElementById('networkPanel').hidden||!document.getElementById('updatesPanel').hidden))closeTopPanels();\n});\n(async()=>{const el=document.getElementById('sections');try{el.textContent='Łączenie z Runicznym Duchem…';state=await req('/api/state');\n  if(!state||!Array.isArray(state.channels)||state.channels.length!==5)throw Error('Niekompletna odpowiedź /api/state');\n  paint();document.getElementById('homeSsid').value=state.wifiSsid||'';document.documentElement.dataset.uiReady='1';setInterval(refresh,5000);syncClock().then(refresh);\n}catch(e){el.textContent='BŁĄD PANELU: '+(e&&e.message?e.message:String(e));}})();\n</script></body></html>\n";
